// src/components/Protected/ProtectedRoute.jsx
import { Navigate } from 'react-router-dom';

const ProtectedRoute = ({ children, allowedRoles = [] }) => {
  const token = localStorage.getItem('token');
  const userStr = localStorage.getItem('user');

  // If no token or user, redirect to login
  if (!token || !userStr) {
    return <Navigate to="/login" replace />;
  }

  // Parse user data
  let user;
  try {
    user = JSON.parse(userStr);
  } catch (err) {
    console.error('Failed to parse user data:', err);
    localStorage.removeItem('user');
    localStorage.removeItem('token');
    return <Navigate to="/login" replace />;
  }

  // Check if route has role restrictions
  if (allowedRoles.length > 0) {
    const userRole = user.role?.toLowerCase();
    const hasAccess = allowedRoles.some(role => role.toLowerCase() === userRole);
    
    if (!hasAccess) {
      // Redirect to appropriate dashboard based on user's role
      switch(userRole) {
        case 'admin':
          return <Navigate to="/admin/dashboard" replace />;
        case 'receptionist':
          return <Navigate to="/receptionist/booking-list" replace />;
        case 'maintenance':
          return <Navigate to="/maintenance/requests" replace />;
        case 'customer':
        default:
          return <Navigate to="/home" replace />;
      }
    }
  }

  // If authenticated and authorized, render the children
  return children;
};

export default ProtectedRoute;
